import requests

url = "https://your-subdomain.tessian-platform.com/reporting/triggers/v1"

parameters = {
    "start_date": "2019-11-15",
    "limit": 100,
}

headers = {
    "Authorization": "API-Token your-api-token",
}

response = requests.get(
    url,
    headers=headers,
    params=parameters,
)
